import { GodRays, type GodRaysProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#5a5a7e", "#8a8a95", "#ffffff", "#3a3a5c"];

interface ShaderGodRaysProps
  extends Omit<GodRaysProps, "frame" | "ref"> {}

function ShaderGodRaysBase({
  speed = 1,
  colorBack = "#12121a",
  colorBloom = "#3a3a5c",
  colors = NEUTRAL_COLORS,
  intensity = 0.8,
  density = 0.3,
  bloom = 0.4,
  className,
  ...rest
}: ShaderGodRaysProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-god-rays"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <GodRays
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colorBloom={colorBloom}
        colors={colors}
        intensity={intensity}
        density={density}
        bloom={bloom}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  intensity: {
    type: "number",
    min: 0,
    max: 2,
    step: 0.05,
    default: 0.8,
    description: "Intensity",
    hiddenFromList: false,
  },
  density: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.3,
    description: "Density",
    hiddenFromList: false,
  },
  bloom: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.4,
    description: "Bloom",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","intensity","density","bloom","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  intensity: 0.8,
  density: 0.3,
  bloom: 0.4,
  colorBack: "#12121a",
};

type ShaderGodRaysElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderGodRaysBase>;

const ShaderGodRaysInner = forwardRef<
  HTMLDivElement,
  ShaderGodRaysElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderGodRays>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderGodRaysBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderGodRaysBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderGodRays = Interactive.withSchema({
  Component: ShaderGodRaysInner,
  componentName: "<ShaderGodRays>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
